"""This function converts the input parameter into a boolean
    Args:
        v (*): input argument
    Returns:
        True: if the input argument is 'yes', 'true', 't', 'y', '1'
        False: if the input argument is 'no', 'false', 'f', 'n', '0'
    Raises:
        ValueError: if the input argument is none of the above
    """
def str2bool(v: str) -> bool {
    if isinstance(v, bool) {
        return v;
    }
    if (v.lower() in ('yes', 'true', 't', 'y', '1')) {
        return True;
    } elif (v.lower() in ('no', 'false', 'f', 'n', '0')) {
        return False;
    } else {
        raise ValueError('Boolean value expected.');
    }
}

"""Returns file size qualifier"""
def get_qual(fsize: Any) -> object {
    if (fsize > (2 ** 30)) {
        fsize = fsize / (2 ** 30);
        qual = 'Giga';
    } elif (fsize > (2 ** 20)) {
        fsize = fsize / (2 ** 20);
        qual = 'Mega';
    } elif (fsize > (2 ** 10)) {
        fsize = fsize / (2 ** 10);
        qual = 'Kilo';
    } else {
        qual = '';
    }
    fsize = round(fsize, 2);
    return (fsize, qual);
}

